"use client";

import Engine from "./multi-level-drawer-menu-engine.jsx";
import css from "./multi-level-drawer-menu-styles";

export interface DrawerLink {
  label: string;
  href: string;
}
export interface DrawerPrimary {
  id: string;
  label: string;
  href?: string;
}
export interface DrawerCard {
  src: string;
  alt?: string;
  label: string;
  href?: string;
}
export interface MultiLevelDrawerMenuProps {
  className?: string;
  duration?: number;
  ease?: string;
  stagger?: number;
  panelBg?: string;
  logo?: string;
  primaries?: DrawerPrimary[];
  sublists?: Record<string, (string | DrawerLink)[]>;
  secondaryLinks?: DrawerLink[];
  cards?: DrawerCard[];
  heroEyebrow?: string;
  heroHeading?: string;
  heroSub?: string;
  heroImage?: string;
  exploreHref?: string;
  onOpenChange?: (open: boolean) => void;
  onNavigate?: (href: string) => void;
}

export function MultiLevelDrawerMenu(props: MultiLevelDrawerMenuProps) {
  return (
    <>
      <style>{css}</style>
      <Engine {...props} />
    </>
  );
}

import type { MultiLevelDrawerMenuProps } from "./multi-level-drawer-menu";
import type { ComponentType } from "react";
declare const Engine: ComponentType<MultiLevelDrawerMenuProps>;
export default Engine;
